// Offline scripted check of the Orbital Transfer layer on the real Earth orbital network
// (src/assets/data/initial_world_state.json, GENERATED by tools/colonization_lab/sol_network.py).
//
//   EliteOrbitalTransferCheck [--world path] [--dt 0.05] [--out D:/tmp/elite_orbital_transfer.txt]
//
// For Vysokiy -> every other Earth hub (two departure epochs) it plans the transfer against the
// MOVING destination ephemeris, then executes it with the carrier law (feed-forward + real gravity +
// PD, clamped to the Cobra main-engine capability) and checks: feasible plan, minimum altitude,
// speed above the tactical 500 m/s, arrival position at the approach point, arrival velocity matched
// to the destination hub's world velocity at the arrival epoch, thrust envelope. Gravity checks: the
// coasting carrier stays in orbit; a carrier slowed by 300 m/s falls into the atmosphere.
// Exit code 1 on any failure.
#include <cmath>
#include <cstdio>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

#include <nlohmann/json.hpp>

#include "src/game/navigation/orbital/OrbitalTransferPlanner.h"

namespace orb = game::navigation::orbital;

struct Hub
{
    std::string id, name;
    world::orbits::OrbitalMotion motion;
};

int main(int argc, char** argv)
{
    std::string worldPath = "src/assets/data/initial_world_state.json";
    std::string outPath = "D:/tmp/elite_orbital_transfer.txt";
    double dt = 0.05;
    for (int i = 1; i + 1 < argc; i += 2)
    {
        const std::string a = argv[i];
        if (a == "--world") worldPath = argv[i + 1];
        else if (a == "--dt") dt = std::stod(argv[i + 1]);
        else if (a == "--out") outPath = argv[i + 1];
    }
    std::ifstream in(worldPath);
    if (!in)
    {
        std::cerr << "cannot open " << worldPath << "\n";
        return 2;
    }
    nlohmann::json root;
    in >> root;
    orb::CentralBody earth;
    const double cobraMainAccel = 73.549875;     // EliteCobraMk1 forwardMainEngineAccelerationMps2 (7.5 g)
    orb::TransferLimits limits;
    std::vector<Hub> hubs;
    for (const auto& h : root["orbital_hubs"])
    {
        if (h.value("parent_body_id", std::string()) != "system_0.Sol.Земля")
            continue;
        Hub hub;
        hub.id = h["id"];
        hub.name = h["name"];
        const auto& m = h["motion"];
        hub.motion.enabled = true;
        hub.motion.parentRadiusMeters = earth.radiusMeters;
        hub.motion.altitudeMeters = m.value("altitude_km", 0.0) * 1000.0;
        hub.motion.inclinationDeg = m.value("inclination_deg", 0.0);
        hub.motion.longitudeOfAscendingNodeDeg = m.value("longitude_of_ascending_node_deg", 0.0);
        hub.motion.argumentOfPeriapsisDeg = m.value("argument_of_periapsis_deg", 0.0);
        hub.motion.initialPhaseDeg = m.value("initial_phase_deg", 0.0);
        hub.motion.epochSeconds = m.value("epoch_seconds", 0.0);
        hub.motion.orbitalPeriodSeconds = world::orbits::computeCircularOrbitPeriodSeconds(
            earth.radiusMeters, hub.motion.altitudeMeters, earth.muM3s2);
        hubs.push_back(hub);
    }
    std::ofstream out(outPath);
    char line[512];
    auto emit = [&](const std::string& s) { std::cout << s << "\n"; out << s << "\n"; };
    emit("ORBITAL TRANSFER CHECK  world=" + worldPath + "  hubs=" + std::to_string(hubs.size()));
    emit("source -> destination | t0 s | ETA s | path km | sweep deg | peak km/s (vs body) | peak vs target km/s | max thrust m/s2 | dv km/s | "
         "min alt km | target moved km | start |v| / target |v| at ETA m/s | arrival pos err m | arrival rel speed m/s | verdict");
    int failures = 0;
    int openItems = 0;
    const Hub* src = nullptr;
    for (const auto& h : hubs)
        if (h.id == "earth_orbital_hub")
            src = &h;
    if (!src)
    {
        emit("FAIL: earth_orbital_hub missing");
        return 1;
    }
    for (double t0 : {0.0, 3000.0})
    {
        for (const auto& dst : hubs)
        {
            if (dst.id == src->id)
                continue;
            // the ship starts parked 10 km from Vysokiy (player start offset scale) with the hub's velocity
            const glm::dvec3 hp = orb::targetPositionAt(src->motion, t0);
            const glm::dvec3 hv = orb::targetVelocityAt(src->motion, t0);
            const glm::dvec3 p0 = hp + glm::normalize(glm::cross(hp, hv)) * 2500.0 - glm::normalize(hv) * 10000.0;
            const glm::dvec3 v0 = hv;
            const orb::OrbitalTransferPlan plan = orb::planOrbitalTransfer(earth, p0, v0, t0, dst.motion, limits);
            if (!plan.feasible)
            {
                // LEO -> GEO needs a Hohmann / spiral optimisation the planner does not have yet:
                // reported as an open item, never as a pass.
                const bool geo = dst.motion.altitudeMeters > 2.0e7;
                std::snprintf(line, sizeof(line), "%s -> %s | %.0f | -- infeasible: %s (%d candidates) | %s", src->name.c_str(), dst.name.c_str(), t0,
                              plan.reason.c_str(), plan.candidatesTried, geo ? "OPEN (LEO->GEO: no Hohmann/spiral optimisation yet)" : "FAIL");
                emit(line);
                if (geo)
                    ++openItems;
                else
                    ++failures;
                continue;
            }
            orb::TransferCarrier c;
            c.positionMeters = p0;
            c.velocityMps = v0;
            c.timeSeconds = t0;
            double maxThrust = 0.0;
            double minAlt = 1.0e30;
            while (c.timeSeconds < plan.arrivalTimeSeconds - 1.0e-9)
            {
                const double step = std::min(dt, plan.arrivalTimeSeconds - c.timeSeconds);
                orb::stepCarrier(plan, earth, c, step, cobraMainAccel);
                maxThrust = std::max(maxThrust, glm::length(c.thrustMps2));
                minAlt = std::min(minAlt, glm::length(c.positionMeters) - earth.radiusMeters);
            }
            const glm::dvec3 tp = orb::targetPositionAt(dst.motion, c.timeSeconds);
            const glm::dvec3 tv = orb::targetVelocityAt(dst.motion, c.timeSeconds);
            const double posErr = glm::length(c.positionMeters - plan.arrivalPositionMeters);
            const double relSpeed = glm::length(c.velocityMps - tv);
            const double moved = glm::length(tp - orb::targetPositionAt(dst.motion, t0)) / 1000.0;
            const double distToHub = glm::length(c.positionMeters - tp);
            const bool ok = posErr < 100.0 && relSpeed < 30.0 && minAlt > earth.minAltitudeMeters - 1.0 && plan.peakSpeedVsTargetMps > 500.0 &&
                            maxThrust <= limits.maxThrustAccelMps2 * 1.15 && distToHub > 5000.0 && distToHub < 30000.0;
            if (!ok)
                ++failures;
            std::snprintf(line, sizeof(line),
                          "%s -> %s | %.0f | %.0f | %.0f | %.1f | %.2f | %.2f | %.2f | %.2f | %.0f | %.0f | %.0f / %.0f | %.1f | %.1f (hub %.1f km away) | %s",
                          src->name.c_str(), dst.name.c_str(), t0, plan.durationSeconds(), plan.pathLengthMeters / 1000.0, plan.sweepRad * 57.29578,
                          plan.peakSpeedMps / 1000.0, plan.peakSpeedVsTargetMps / 1000.0, maxThrust, c.deltaVUsedMps / 1000.0, minAlt / 1000.0, moved,
                          glm::length(v0), glm::length(tv), posErr, relSpeed, distToHub / 1000.0, ok ? "PASS" : "FAIL");
            emit(line);
        }
    }
    // gravity is real: coasting stays in orbit, a slowed carrier falls
    {
        const glm::dvec3 hp = orb::targetPositionAt(src->motion, 0.0);
        const glm::dvec3 hv = orb::targetVelocityAt(src->motion, 0.0);
        orb::OrbitalTransferPlan none;
        orb::TransferCarrier c;
        c.positionMeters = hp;
        c.velocityMps = hv;
        double lo = 1.0e30, hi = 0.0;
        const double period = src->motion.orbitalPeriodSeconds;
        for (double t = 0.0; t < period; t += 0.05)
        {
            orb::stepCarrier(none, earth, c, 0.05, cobraMainAccel, false);
            const double alt = glm::length(c.positionMeters) - earth.radiusMeters;
            lo = std::min(lo, alt);
            hi = std::max(hi, alt);
        }
        const bool coastOk = lo > 419000.0 - 2000.0 && hi < 421000.0 + 2000.0;
        std::snprintf(line, sizeof(line), "coast, thrust off, one orbit from Vysokiy: altitude %.1f .. %.1f km | %s", lo / 1000.0, hi / 1000.0, coastOk ? "PASS" : "FAIL");
        emit(line);
        failures += coastOk ? 0 : 1;
        c = orb::TransferCarrier {};
        c.positionMeters = hp;
        c.velocityMps = hv - glm::normalize(hv) * 300.0;
        double minAlt = 1.0e30;
        double tFall = -1.0;
        for (double t = 0.0; t < period; t += 0.05)
        {
            orb::stepCarrier(none, earth, c, 0.05, cobraMainAccel, false);
            minAlt = std::min(minAlt, glm::length(c.positionMeters) - earth.radiusMeters);
            if (minAlt < 100000.0 && tFall < 0.0)
                tFall = t;
        }
        const bool fallOk = tFall > 0.0;
        std::snprintf(line, sizeof(line), "coast after a 300 m/s retro burn: perigee below 100 km after %.0f s (min %.1f km) | %s", tFall, minAlt / 1000.0,
                      fallOk ? "PASS" : "FAIL");
        emit(line);
        failures += fallOk ? 0 : 1;
    }
    // Earth hub -> Ceres hub: the same plan type in compressed time (star-relative), checked on the real data
    for (const auto& h : root["orbital_hubs"])
    {
        if (h.value("parent_body_id", std::string()) != "system_0.Sol")
            continue;
        world::orbits::OrbitalMotion cm;
        const auto& m = h["motion"];
        const double rSun = 695700000.0, muSun = 1.32712440018e20;
        cm.enabled = true;
        cm.parentRadiusMeters = rSun;
        cm.altitudeMeters = m.value("altitude_km", 0.0) * 1000.0;
        cm.inclinationDeg = m.value("inclination_deg", 0.0);
        cm.longitudeOfAscendingNodeDeg = m.value("longitude_of_ascending_node_deg", 0.0);
        cm.initialPhaseDeg = m.value("initial_phase_deg", 0.0);
        cm.orbitalPeriodSeconds = world::orbits::computeCircularOrbitPeriodSeconds(rSun, cm.altitudeMeters, muSun);
        // Earth on a 1 AU circle at t0 = 0 (+X), the ship at Vysokiy's offset from Earth
        const glm::dvec3 earthPos(1.495978707e11, 0.0, 0.0), earthVel(0.0, 0.0, 29780.0);
        const glm::dvec3 p0 = earthPos + orb::targetPositionAt(src->motion, 0.0);
        const glm::dvec3 v0 = earthVel + orb::targetVelocityAt(src->motion, 0.0);
        const orb::OrbitalTransferPlan plan = orb::planCompressedTransit(p0, v0, 0.0, cm, limits, 90.0);
        const auto end = orb::evaluateCompressed(plan, plan.arrivalTimeSeconds);
        const glm::dvec3 tv = orb::targetVelocityAt(cm, plan.arrivalTimeSeconds);
        const glm::dvec3 tp = orb::targetPositionAt(cm, plan.arrivalTimeSeconds);
        double minSun = 1.0e30;
        for (const auto& p : plan.tunnelMeters)
            minSun = std::min(minSun, glm::length(p));
        const bool ok = plan.compressed && glm::length(end.velocityMps - tv) < 25.0 && std::abs(glm::length(end.positionMeters - tp) - limits.approachOffsetMeters) < 100.0 &&
                        minSun > 0.6 * 1.495978707e11;
        std::snprintf(line, sizeof(line), "%s -> %s (compressed time, same plan type): tunnel %.2f AU, closest to the Sun %.2f AU, physical %.2f d, "
                      "arrival %.1f km from the hub, relative %.1f m/s | %s", src->name.c_str(), h["name"].get<std::string>().c_str(), plan.pathLengthMeters / 1.495978707e11,
                      minSun / 1.495978707e11, plan.physicalDurationSeconds / 86400.0, glm::length(end.positionMeters - tp) / 1000.0, glm::length(end.velocityMps - tv),
                      ok ? "PASS" : "FAIL");
        emit(line);
        failures += ok ? 0 : 1;
    }
    // Earth -> Ceres: the physical leg an abstracted transit stands for (Cobra at the sustained transfer envelope)
    for (double d : {1.77, 2.77, 3.77})
    {
        const orb::InterplanetaryEstimate e = orb::brachistochrone(d * 1.495978707e11, limits.maxThrustAccelMps2);
        std::snprintf(line, sizeof(line), "Earth -> Ceres at %.2f AU: brachistochrone %.2f days at %.1f m/s2, peak %.0f km/s, dv %.0f km/s",
                      d, e.durationSeconds / 86400.0, e.accelMps2, e.peakSpeedMps / 1000.0, e.deltaVMps / 1000.0);
        emit(line);
    }
    emit(failures ? "ORBITAL TRANSFER CHECK: FAILED (" + std::to_string(failures) + ")"
                  : "ORBITAL TRANSFER CHECK: PASS (LEO network)" + (openItems ? ", OPEN items: " + std::to_string(openItems) : std::string()));
    return failures ? 1 : 0;
}
